/*
 * MOS Scene Hunt service worker.
 *
 * Hand-written rather than generated by a build plugin, for two reasons:
 *  1. It keeps the dependency tree small, which makes the licence audit simpler.
 *  2. The offline rules this game needs are specific and worth stating plainly:
 *     the shell and the content pack must survive with no network, but GPS has
 *     nothing to do with the network and must never be gated on connectivity.
 *
 * Strategy per request class:
 *   - navigation  : network-first, fall back to the cached app shell
 *   - /content/*  : network-first, fall back to the cache (content packs are the
 *                   one thing we want fresh when online)
 *   - /_next/static, /icons, same-origin assets : cache-first (immutable)
 *   - cross-origin tiles : stale-while-revalidate, and never block on failure
 */

const VERSION = "v1";
const SHELL_CACHE = `mos-shell-${VERSION}`;
const ASSET_CACHE = `mos-assets-${VERSION}`;
const CONTENT_CACHE = `mos-content-${VERSION}`;
const TILE_CACHE = `mos-tiles-${VERSION}`;

/** Routes that must work offline. */
const SHELL_ROUTES = ["/", "/select", "/map", "/quest", "/bag"];

/** Cap the tile cache so a long walk cannot exhaust the storage quota. */
const TILE_CACHE_LIMIT = 400;

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(SHELL_CACHE);
      // Precache the shell. Individual failures must not abort the install, or a
      // single missing route would leave the app with no service worker at all.
      await Promise.all(
        SHELL_ROUTES.map((route) =>
          cache.add(new Request(route, { cache: "reload" })).catch(() => undefined),
        ),
      );
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      const keep = new Set([SHELL_CACHE, ASSET_CACHE, CONTENT_CACHE, TILE_CACHE]);
      await Promise.all(keys.filter((k) => !keep.has(k)).map((k) => caches.delete(k)));
      await self.clients.claim();
    })(),
  );
});

/** Trim a cache to its most recent N entries. */
async function trimCache(cacheName, limit) {
  const cache = await caches.open(cacheName);
  const keys = await cache.keys();
  if (keys.length <= limit) return;
  for (const key of keys.slice(0, keys.length - limit)) {
    await cache.delete(key);
  }
}

function isTileRequest(url) {
  return (
    url.hostname.includes("tile.openstreetmap.org") ||
    url.hostname.includes("tile.openstreetmap.fr") ||
    url.hostname.includes("basemaps.cartocdn.com") ||
    url.hostname.includes("tile.openstreetmap.de")
  );
}

async function networkFirst(request, cacheName, { timeoutMs } = {}) {
  const cache = await caches.open(cacheName);
  try {
    const response = await withTimeout(fetch(request), timeoutMs);
    if (response && response.ok) {
      cache.put(request, response.clone());
    }
    return response;
  } catch (err) {
    const cached = await cache.match(request, { ignoreSearch: true });
    if (cached) return cached;
    throw err;
  }
}

async function cacheFirst(request, cacheName) {
  const cache = await caches.open(cacheName);
  const cached = await cache.match(request);
  if (cached) return cached;
  const response = await fetch(request);
  if (response && response.ok) cache.put(request, response.clone());
  return response;
}

async function staleWhileRevalidate(request, cacheName, limit) {
  const cache = await caches.open(cacheName);
  const cached = await cache.match(request);
  const fetching = fetch(request)
    .then((response) => {
      if (response && (response.ok || response.type === "opaque")) {
        cache.put(request, response.clone());
        void trimCache(cacheName, limit);
      }
      return response;
    })
    .catch(() => undefined);
  // Serve the cached tile immediately; the refresh happens in the background.
  return cached || (await fetching) || Response.error();
}

function withTimeout(promise, ms) {
  if (!ms) return promise;
  return Promise.race([
    promise,
    new Promise((_, reject) => setTimeout(() => reject(new Error("sw-timeout")), ms)),
  ]);
}

self.addEventListener("fetch", (event) => {
  const { request } = event;

  // Only GET is cacheable, and we must never interfere with an API mutation.
  if (request.method !== "GET") return;

  const url = new URL(request.url);

  // Never cache or intercept chrome-extension and other exotic schemes.
  if (!url.protocol.startsWith("http")) return;

  // Game content packs: freshest wins online, cache saves us offline.
  if (url.origin === self.location.origin && url.pathname.startsWith("/content/")) {
    event.respondWith(networkFirst(request, CONTENT_CACHE, { timeoutMs: 5000 }));
    return;
  }

  // Map tiles: stale-while-revalidate so panning stays smooth and a previously
  // viewed area keeps working with no signal.
  if (isTileRequest(url)) {
    event.respondWith(staleWhileRevalidate(request, TILE_CACHE, TILE_CACHE_LIMIT));
    return;
  }

  // App navigations: network-first, then the shell. This is what makes a
  // refresh while offline land on a working page instead of the browser error.
  if (request.mode === "navigate") {
    event.respondWith(
      (async () => {
        try {
          const response = await withTimeout(fetch(request), 4000);
          if (response && response.ok) {
            const cache = await caches.open(SHELL_CACHE);
            cache.put(request, response.clone());
          }
          return response;
        } catch {
          const cache = await caches.open(SHELL_CACHE);
          const direct = await cache.match(request);
          if (direct) return direct;
          // SPA fallback: serve the root shell for any unknown route.
          const shell = await cache.match("/");
          if (shell) return shell;
          return new Response(
            offlineFallbackHtml(),
            { status: 200, headers: { "Content-Type": "text/html; charset=utf-8" } },
          );
        }
      })(),
    );
    return;
  }

  // Same-origin static assets: immutable, so cache-first is correct.
  if (url.origin === self.location.origin) {
    event.respondWith(
      cacheFirst(request, ASSET_CACHE).catch(() => caches.match(request).then((r) => r || Response.error())),
    );
    return;
  }
});

function offlineFallbackHtml() {
  return `<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>MOS Scene Hunt · 离线</title>
<style>
  body{margin:0;min-height:100dvh;display:grid;place-items:center;background:#f6f7fb;
       font:16px/1.6 system-ui,-apple-system,"PingFang SC","Microsoft YaHei",sans-serif;color:#101527;padding:24px}
  .c{max-width:420px;text-align:center}
  h1{font-size:19px;margin:0 0 8px}
  p{font-size:14px;color:#5f6779;margin:0 0 6px}
  .b{display:inline-block;margin-top:16px;padding:13px 22px;border-radius:14px;background:#f5a524;
     color:#2b1a00;font-weight:600;text-decoration:none}
</style></head>
<body><div class="c">
  <h1>当前处于离线状态</h1>
  <p>这个页面还没有被缓存到本机。</p>
  <p>如果你之前已经打开过游戏，请从下面的入口进入——已缓存的游戏仍可继续，GPS 也不需要网络。</p>
  <a class="b" href="/map">尝试进入游戏地图</a>
</div></body></html>`;
}

/*
 * Cross-tab broadcast: lets an open tab learn that a newer build is waiting,
 * so V0.2 can prompt "有新版本" instead of forcing a silent reload mid-hunt.
 */
self.addEventListener("message", (event) => {
  if (event.data?.type === "SKIP_WAITING") void self.skipWaiting();
});
